{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance Metadata Service v1 is enabled",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "The launch template does not require IMDSv2, allowing instances to accept less secure IMDSv1 requests. This increases the risk of credential theft through server-side request forgery or compromised processes."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Secrets exposed in instance user data",
      "resource": "aws_launch_template.web_app",
      "severity": "HIGH",
      "explanation": "The database password and a hardcoded API key are embedded in launch template user data, exposing them through Terraform state, AWS APIs, and instance metadata. Anyone able to read those locations could recover the credentials."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Root volume encryption is not enforced",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "The launch template does not explicitly encrypt its root EBS volume. If the selected AMI and account defaults do not provide encryption, application and operating-system data could be stored unencrypted."
    }
  ],
  "patched_code": "resource "aws_launch_template" "web_app" {
  name_prefix   = "automated-employee-onboarding-platform-lt-web-"
  image_id      = data.aws_ami.ubuntu.id
  instance_type = var.instance_type
  key_name      = var.key_pair_name
  vpc_security_group_ids = [aws_security_group.web_app.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  block_device_mappings {
    device_name = data.aws_ami.ubuntu.root_device_name

    ebs {
      encrypted = true
    }
  }

  user_data = base64encode(<<-EOF
              apt-get update
              apt-get install -y nginx nodejs npm
              systemctl start nginx
              systemctl enable nginx
              EOF
  )
  tag_specifications {
    resource_type = "instance"
  }
}
",
  "fix_summary": "Required IMDSv2 and explicitly enabled encryption for the AMI root EBS volume. Removed the database password and hardcoded API key from instance user data so credentials are no longer persisted in the launch template or Terraform state."
}
